/**
  \rst
  The ``printf`` argument formatter.
  \endrst
 */
template <typename Range>
class printf_arg_formatter : public detail::arg_formatter_base<Range> {
 public:
  using iterator = typename Range::iterator;

 private:
  using char_type = typename Range::value_type;
  using base = detail::arg_formatter_base<Range>;
  using context_type = basic_printf_context<iterator, char_type>;

  context_type& context_;

  void write_null_pointer(char) {
    this->specs()->type = 0;
    this->write("(nil)");
  }

  void write_null_pointer(wchar_t) {
    this->specs()->type = 0;
    this->write(L"(nil)");
  }

 public:
  using format_specs = typename base::format_specs;

  /**
    \rst
    Constructs an argument formatter object.
    *buffer* is a reference to the output buffer and *specs* contains format
    specifier information for standard argument types.
    \endrst
   */
  printf_arg_formatter(iterator iter, format_specs& specs, context_type& ctx)
      : base(Range(iter), &specs, detail::locale_ref()), context_(ctx) {}

  template <typename T, FMT_ENABLE_IF(fmt::detail::is_integral<T>::value)>
  iterator operator()(T value) {
    // MSVC2013 fails to compile separate overloads for bool and char_type so
    // use std::is_same instead.
    format_specs& fmt_specs = *this->specs();
    iterator out = this->out();
    if (std::is_same<T, bool>::value && fmt_specs.type == 's') {
      fmt_specs.type = 0;
      const char* literal = "false";
      size_t size = 5;
      if (value != 0) {
        literal = "true";
        size = 4;
      }
      if (fmt_specs.precision >= 0) {
        if (detail::to_unsigned(fmt_specs.precision) < size) {
          size = detail::to_unsigned(fmt_specs.precision);
        }
      }
      unsigned spec_width = detail::to_unsigned(fmt_specs.width);
      size_t padding = 0;
      if (spec_width > size) {
        padding = spec_width - size;
      }
      size_t left_padding =
          padding >> detail::data::left_padding_shifts[fmt_specs.align];
      auto it = detail::reserve(out, size + padding * fmt_specs.fill.size());
      if (left_padding != 0) {
        it = detail::fill(it, left_padding, fmt_specs.fill);
      }
      it = detail::copy_str<char_type>(literal, literal + size, it);
      if (padding > left_padding) {
        it = detail::fill(it, padding - left_padding, fmt_specs.fill);
      }
      return detail::base_iterator(out, it);
    }
    if (std::is_same<T, char_type>::value) {
      if (fmt_specs.type && fmt_specs.type != 'c')
        return (*this)(static_cast<int>(value));
      fmt_specs.sign = sign::none;
      fmt_specs.alt = false;
      fmt_specs.align = align::right;
      return base::operator()(value);
    }

    using uint_type = detail::uint32_or_64_or_128_t<T>;
    uint_type abs_value = static_cast<uint_type>(value);
    char prefix[4];
    unsigned prefix_size = 0;
    if (detail::is_negative(value)) {
      prefix[0] = '-';
      prefix_size = 1;
      abs_value = static_cast<uint_type>(0) - abs_value;
    } else if (fmt_specs.sign == sign::plus) {
      prefix[0] = '+';
      prefix_size = 1;
    } else if (fmt_specs.sign == sign::space) {
      prefix[0] = ' ';
      prefix_size = 1;
    }

    if (fmt_specs.type == 0 || fmt_specs.type == 'd') {
      int num_digits = detail::count_digits(abs_value);
      size_t size = prefix_size + detail::to_unsigned(num_digits);
      size_t digit_padding = 0;
      if (fmt_specs.align == align::numeric) {
        unsigned width = detail::to_unsigned(fmt_specs.width);
        if (width > size) {
          digit_padding = width - size;
          size = width;
        }
      } else if (fmt_specs.precision > num_digits) {
        size = prefix_size + detail::to_unsigned(fmt_specs.precision);
        digit_padding =
            detail::to_unsigned(fmt_specs.precision - num_digits);
      }
      unsigned spec_width = detail::to_unsigned(fmt_specs.width);
      size_t padding = 0;
      if (spec_width > size) {
        padding = spec_width - size;
      }
      size_t left_padding =
          padding >> detail::data::right_padding_shifts[fmt_specs.align];
      auto it = detail::reserve(out, size + padding * fmt_specs.fill.size());
      if (left_padding != 0) {
        size_t fill_size = fmt_specs.fill.size();
        if (fill_size == 1) {
          it = std::fill_n(it, left_padding, fmt_specs.fill[0]);
        } else {
          const char_type* fill_data = fmt_specs.fill.data();
          for (size_t n = 0; n < left_padding; ++n) {
            for (size_t k = 0; k < fill_size; ++k) {
              *it++ = fill_data[k];
            }
          }
        }
      }
      if (prefix_size != 0) {
        for (unsigned i = 0; i < prefix_size; ++i) {
          *it++ = static_cast<char_type>(prefix[i]);
        }
      }
      if (digit_padding != 0) {
        it = std::fill_n(it, digit_padding, static_cast<char_type>('0'));
      }
      char_type digit_buf[128];
      char_type* buffer = digit_buf + num_digits;
      char_type* end = buffer;
      uint_type v = abs_value;
      while (v >= 100) {
        unsigned index = static_cast<unsigned>((v % 100) * 2);
        v /= 100;
        *--buffer = static_cast<char_type>(detail::data::digits[index + 1]);
        *--buffer = static_cast<char_type>(detail::data::digits[index]);
      }
      if (v < 10) {
        *--buffer = static_cast<char_type>('0' + static_cast<int>(v));
      } else {
        unsigned index = static_cast<unsigned>(v * 2);
        *--buffer = static_cast<char_type>(detail::data::digits[index + 1]);
        *--buffer = static_cast<char_type>(detail::data::digits[index]);
      }
      it = detail::copy_str<char_type>(buffer, end, it);
      if (padding > left_padding) {
        size_t fill_size = fmt_specs.fill.size();
        size_t right_padding = padding - left_padding;
        if (fill_size == 1) {
          it = std::fill_n(it, right_padding, fmt_specs.fill[0]);
        } else {
          const char_type* fill_data = fmt_specs.fill.data();
          for (size_t n = 0; n < right_padding; ++n) {
            for (size_t k = 0; k < fill_size; ++k) {
              *it++ = fill_data[k];
            }
          }
        }
      }
      return detail::base_iterator(out, it);
    }

    detail::int_writer<iterator, char_type, uint_type> writer(
        out, detail::locale_ref(), value, fmt_specs);
    detail::handle_int_type_spec(fmt_specs.type, writer);
    return writer.out;
  }

  template <typename T, FMT_ENABLE_IF(std::is_floating_point<T>::value)>
  iterator operator()(T value) {
    return base::operator()(value);
  }

  /** Formats a null-terminated C string. */
  iterator operator()(const char* value) {
    if (value)
      base::operator()(value);
    else if (this->specs()->type == 'p')
      write_null_pointer(char_type());
    else
      this->write("(null)");
    return this->out();
  }

  /** Formats a null-terminated wide C string. */
  iterator operator()(const wchar_t* value) {
    if (value)
      base::operator()(value);
    else if (this->specs()->type == 'p')
      write_null_pointer(char_type());
    else
      this->write(L"(null)");
    return this->out();
  }

  iterator operator()(basic_string_view<char_type> value) {
    return base::operator()(value);
  }

  iterator operator()(monostate value) { return base::operator()(value); }

  /** Formats a pointer. */
  iterator operator()(const void* value) {
    if (value) return base::operator()(value);
    this->specs()->type = 0;
    write_null_pointer(char_type());
    return this->out();
  }

  /** Formats an argument of a custom (user-defined) type. */
  iterator operator()(typename basic_format_arg<context_type>::handle handle) {
    handle.format(context_.parse_context(), context_);
    return this->out();
  }
};

template <typename T> struct printf_formatter {
  printf_formatter() = delete;

  template <typename ParseContext>
  auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return ctx.begin();
  }

  template <typename FormatContext>
  auto format(const T& value, FormatContext& ctx) -> decltype(ctx.out()) {
    detail::format_value(detail::get_container(ctx.out()), value);
    return ctx.out();
  }
};

